# Patch 2026-09-08: UX-Durchgang ueber alle Reiter
# - Lange Listen/Tabellen scrollbar (Content-Zitate, Massnahmen-Rangfolge, LinkedIn-Posts,
#   Presse-Artikel, GEO-Produktkarten, Check24-Tabelle) mit Sticky-Headern
# - Korrelations-Reiter Klartext: Antwort + Hebel sichtbar, 5 Analyse-Abschnitte in Aufklappern
# Idempotent je Datei per Signatur.
import base64, sys
def wende_an(pfad, paare, signatur, erwartete_counts):
    s = open(pfad,'rb').read()
    if signatur.encode() in s:
        print('SKIP', pfad); return
    for (a,n),cnt in zip(paare, erwartete_counts):
        alt, neu = base64.b64decode(a), base64.b64decode(n)
        if s.count(alt) != cnt:
            print('FEHLER', pfad, 'erwartet', cnt, 'gefunden', s.count(alt)); sys.exit(1)
        s = s.replace(alt, neu)
    open(pfad,'wb').write(s)
    print('OK', pfad)

